-- 미용(beauty) 카테고리 첫 단어 3개: 수부지 / 닦토 / 흡토 (486-488, 2026-09-13, 운영자 지시 — 직접 추가).
-- 카테고리 자체는 src/features/categories/model/categories.ts의 CATEGORIES에 slug 'beauty'로 추가
-- (words.category는 CHECK 제약 없는 text라 DB 스키마 변경 없음).
-- [표준사전: 없음] 세 단어 모두 표준국어대사전 검색 0건(직접 확인).
-- 수부지: '수분 부족형 지성' 줄임말. 출처 리빙센스 '수부지에 관한 모든 것', 브런치 지성·수부지 케어 글,
--   나무위키 피부/타입, 바다사전. 언제 처음 줄여 썼는지는 특정되지 않아 시기를 적지 않았다.
-- 닦토·흡토: '닦는 토너'·'흡수(시키는) 토너' 줄임말. 출처 코메디닷컴('토너, 닦을까? 바를까?'),
--   씽크닥터('닦토' 효과), Threads 뷰티 계정의 닦토/흡토/팩토 정리. 팩토는 출처 한 곳뿐이라 넣지 않았다.
-- 표제어 규칙(형태 변이): 줄임말이 통용형이라 표제어로, 원말은 aliases.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations, aliases) values
('486', '수부지', 'Su-bu-ji', 'beauty', null, '''수분 부족형 지성'' — 겉은 번들, 속은 건조한 피부', '{"de": "Kurz für „dehydrierte fettige Haut“ — außen glänzend, innen trocken", "en": "Short for “dehydrated oily skin” — shiny outside, dry underneath", "es": "Abreviatura de “piel grasa deshidratada”: brillante por fuera, seca por dentro", "ja": "「水分不足型脂性肌」の略 — 表面はテカるのに内側は乾燥", "vi": "Viết tắt của “da dầu thiếu nước” — ngoài bóng dầu, trong khô"}'::jsonb, null, '[{"type": "명사", "definition": "''수분 부족형 지성''을 줄인 말. 피부 겉은 기름기가 돌아 번들거리는데 속은 수분이 모자라 당기고 건조한 피부 타입을 가리킨다. 지성 피부처럼 보여서 기름기만 잡으려다 속건조가 더 심해지기 쉽다는 점 때문에, 뷰티 커뮤니티에서는 일반 지성과 구분해 이 이름으로 부른다.", "definition_i18n": {"de": "Kurzform von 수분 부족형 지성, „dehydrierte fettige Haut“: ein Hauttyp, der an der Oberfläche fettig glänzt, darunter aber Feuchtigkeit vermisst, spannt und trocken ist. Weil er wie normale fettige Haut aussieht, verschlimmert man die innere Trockenheit leicht, wenn man nur das Fett bekämpft — deshalb unterscheiden Beauty-Communitys ihn mit diesem eigenen Namen.", "en": "A clipping of 수분 부족형 지성, “dehydrated oily skin”: a skin type that looks greasy and shiny on the surface but lacks moisture underneath, so it feels tight and dry. Because it passes for ordinary oily skin, people easily make the inner dryness worse by only fighting the oil — which is why beauty communities give it its own name.", "es": "Acortamiento de 수분 부족형 지성, “piel grasa deshidratada”: un tipo de piel que brilla por la grasa en la superficie pero a la que le falta agua por dentro, así que tira y se nota seca. Como parece piel grasa normal, es fácil empeorar la sequedad interna atacando solo la grasa; por eso las comunidades de belleza la llaman con este nombre propio.", "ja": "「수분 부족형 지성(水分不足型脂性肌)」の略。肌の表面は皮脂でテカるのに、内側は水分が足りずつっぱって乾燥する肌タイプ。普通の脂性肌に見えるため皮脂対策だけをして内側の乾燥を悪化させやすく、美容コミュニティでは一般的な脂性肌と区別してこの名前で呼ぶ。日本語の「インナードライ肌」に近い。", "vi": "Dạng rút gọn của 수분 부족형 지성, “da dầu thiếu nước”: loại da bề mặt đổ dầu bóng nhờn nhưng bên trong lại thiếu nước nên căng và khô. Vì trông giống da dầu thông thường nên người ta dễ làm tình trạng khô bên trong nặng thêm khi chỉ lo kiềm dầu — vì vậy cộng đồng làm đẹp gọi riêng bằng cái tên này."}, "examples": [{"kor": "T존은 번들거리는데 볼은 당겨. 나 수부지인가 봐.", "eng": "My T-zone gets shiny but my cheeks feel tight. I think I have dehydrated oily skin.", "ja": "Tゾーンはテカるのに頬はつっぱる。私、インナードライなのかも。", "es": "La zona T me brilla pero las mejillas me tiran. Creo que tengo la piel grasa deshidratada.", "vi": "Vùng chữ T thì bóng dầu mà má lại căng. Chắc mình là da dầu thiếu nước rồi.", "de": "Meine T-Zone glänzt, aber die Wangen spannen. Ich glaube, ich habe dehydrierte fettige Haut."}, {"kor": "수부지는 유분만 잡지 말고 수분부터 채워야 한대.", "eng": "They say with dehydrated oily skin you should add moisture first instead of just controlling oil.", "ja": "インナードライは皮脂だけ抑えるんじゃなくて、まず水分を補わなきゃいけないんだって。", "es": "Dicen que con piel grasa deshidratada primero hay que hidratar, no solo controlar la grasa.", "vi": "Nghe nói da dầu thiếu nước thì phải cấp nước trước chứ không chỉ kiềm dầu.", "de": "Bei dehydrierter fettiger Haut soll man erst Feuchtigkeit geben, statt nur das Fett zu bekämpfen."}]}]'::jsonb, '피부 타입을 나누는 말인 ''수분 부족형 지성''(영어권의 dehydrated oily skin에 해당)을 세 글자로 줄인 말이다. 화장품 업계와 뷰티 커뮤니티에서 피부 타입 분류 용어로 쓰이다가 줄임말로 굳었고, 지금은 제품 후기·피부 고민 글에서 흔히 쓴다. 언제 누가 처음 줄여 썼는지는 확인되지 않는다.', '{"de": "Eine dreisilbige Kurzform der Hauttyp-Bezeichnung 수분 부족형 지성 (entspricht dem englischen „dehydrated oily skin“). In der Kosmetikbranche und in Beauty-Communitys als Hauttyp-Begriff verwendet, verfestigte sie sich zur Abkürzung und ist heute in Produktbewertungen und Beiträgen zu Hautproblemen üblich. Wann und von wem sie zuerst abgekürzt wurde, ist nicht belegt.", "en": "A three-syllable clipping of the skin-type label 수분 부족형 지성 (the equivalent of “dehydrated oily skin”). Used as a classification term in the cosmetics industry and beauty communities, it settled into this short form and is now common in product reviews and skin-concern posts. When and by whom it was first shortened is not documented.", "es": "Acortamiento de tres sílabas de la etiqueta de tipo de piel 수분 부족형 지성 (equivale a “dehydrated oily skin”). Usada como término de clasificación en la industria cosmética y las comunidades de belleza, se fijó en esta forma corta y hoy es habitual en reseñas de productos y consultas sobre la piel. No consta cuándo ni quién la abrevió primero.", "ja": "肌タイプの分類名「수분 부족형 지성(水分不足型脂性肌)」を3文字に縮めた語で、英語のdehydrated oily skinに当たる。化粧品業界や美容コミュニティで肌タイプの用語として使われるうちに略語として定着し、今では商品レビューや肌の悩み相談の投稿でよく使われる。いつ誰が最初に略したかは確認されていない。", "vi": "Dạng rút gọn ba âm tiết của tên loại da 수분 부족형 지성 (tương đương “dehydrated oily skin”). Được dùng như thuật ngữ phân loại da trong ngành mỹ phẩm và cộng đồng làm đẹp, nó dần thành dạng viết tắt và nay rất phổ biến trong review sản phẩm hay bài hỏi về da. Không rõ ai rút gọn đầu tiên và từ khi nào."}'::jsonb, '''나 수부지야'', ''수부지용 크림''처럼 피부 타입을 말할 때 쓴다. 뷰티 커뮤니티·화장품 후기에서 일상적으로 쓰는 말이라 친구 사이 대화에서도 자연스럽다. ''수부지''와 ''수분 부족형 지성'' 중 어느 쪽으로 검색해도 이 항목 하나로 나온다.', '{"de": "Man benutzt es für den eigenen Hauttyp: 나 수부지야 („ich habe dehydrierte fettige Haut“), 수부지용 크림 („Creme für dehydrierte fettige Haut“). In Beauty-Communitys und Produktbewertungen ist es Alltagswort und klingt auch im Gespräch unter Freunden natürlich. Ob man nach 수부지 oder 수분 부족형 지성 sucht, man landet bei diesem einen Eintrag.", "en": "Used to name your skin type: 나 수부지야 (“I have dehydrated oily skin”), 수부지용 크림 (“cream for dehydrated oily skin”). It is an everyday word in beauty communities and product reviews, so it sounds natural in conversation with friends too. Searching 수부지 or 수분 부족형 지성 brings up this single entry.", "es": "Se usa para decir tu tipo de piel: 나 수부지야 (“tengo la piel grasa deshidratada”), 수부지용 크림 (“crema para piel grasa deshidratada”). Es palabra corriente en comunidades de belleza y reseñas, así que suena natural también entre amigos. Busques 수부지 o 수분 부족형 지성, aparece esta misma entrada.", "ja": "「나 수부지야(私インナードライなんだ)」「수부지용 크림(インナードライ肌用クリーム)」のように肌タイプを言うときに使う。美容コミュニティや化粧品レビューで日常的に使う語なので、友達同士の会話でも自然。「수부지」「수분 부족형 지성」のどちらで検索してもこの項目ひとつが出る。", "vi": "Dùng khi nói về loại da: 나 수부지야 (“tớ da dầu thiếu nước”), 수부지용 크림 (“kem cho da dầu thiếu nước”). Đây là từ thông dụng trong cộng đồng làm đẹp và review mỹ phẩm nên nói chuyện với bạn bè cũng tự nhiên. Tìm 수부지 hay 수분 부족형 지성 đều ra đúng mục này."}'::jsonb, array['흡토','닦토'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Dehydrated oily skin"}, {"lang": "🇯🇵 JA", "text": "インナードライ肌(水分不足型脂性肌)"}, {"lang": "🇨🇳 ZH", "text": "缺水型油性皮肤"}, {"lang": "🇻🇳 VI", "text": "Da dầu thiếu nước"}, {"lang": "🇪🇸 ES", "text": "Piel grasa deshidratada"}, {"lang": "🇩🇪 DE", "text": "Dehydrierte fettige Haut"}]'::jsonb, array['수분 부족형 지성']),
('487', '닦토', 'Dak-to', 'beauty', null, '''닦는 토너'' — 화장솜에 묻혀 닦아 내는 토너 사용법', '{"de": "Kurz für „Abwisch-Toner“ — Toner mit dem Wattepad auftragen und abwischen", "en": "Short for “wipe-off toner” — using toner on a cotton pad to wipe the face", "es": "Abreviatura de “tónico para limpiar”: usar el tónico en un algodón y pasarlo por la cara", "ja": "「拭き取り化粧水」の略 — コットンに含ませて拭き取る使い方", "vi": "Viết tắt của “toner lau” — thấm toner vào bông rồi lau mặt"}'::jsonb, null, '[{"type": "명사", "definition": "''닦는 토너''를 줄인 말. 토너를 화장솜에 묻혀 얼굴을 쓸어 닦아 내는 사용법, 또는 그렇게 쓰도록 만든 토너를 가리킨다. 세안 뒤 남은 잔여물이나 묵은 각질을 정리하는 용도라, 손으로 두드려 흡수시키는 ''흡토''와 짝을 이루는 말로 쓰인다.", "definition_i18n": {"de": "Kurzform von 닦는 토너, „Toner zum Abwischen“: die Methode, Toner auf ein Wattepad zu geben und damit übers Gesicht zu wischen — oder ein Toner, der dafür gedacht ist. Weil es darum geht, Rückstände nach dem Waschen oder abgestorbene Hautschüppchen zu entfernen, wird es als Gegenstück zu 흡토 verwendet, bei dem man den Toner mit den Händen einklopft.", "en": "A clipping of 닦는 토너, “toner for wiping”: the method of putting toner on a cotton pad and sweeping it across the face, or a toner made to be used that way. Since the point is to clear away residue left after cleansing or dead skin flakes, it is used as the counterpart of 흡토, where you pat toner in with your hands.", "es": "Acortamiento de 닦는 토너, “tónico para limpiar”: la forma de usar el tónico empapando un algodón y pasándolo por la cara, o un tónico hecho para eso. Como sirve para retirar restos tras la limpieza o células muertas, se usa como pareja de 흡토, en el que el tónico se aplica a toquecitos con las manos.", "ja": "「닦는 토너(拭き取る化粧水)」の略。化粧水をコットンに含ませて顔を拭き取る使い方、またはそう使うように作られた化粧水を指す。洗顔後の残りや古い角質を整える用途なので、手でたたき込んでなじませる「흡토」と対になる言葉として使われる。", "vi": "Dạng rút gọn của 닦는 토너, “toner để lau”: cách thấm toner vào bông tẩy trang rồi lau khắp mặt, hoặc loại toner làm ra để dùng như vậy. Vì mục đích là làm sạch cặn còn sót sau khi rửa mặt hay tế bào chết, nó được dùng như cặp đôi với 흡토 — vỗ toner cho thấm bằng tay."}, "examples": [{"kor": "아침엔 닦토로 가볍게 정리하고 스킨케어 시작해.", "eng": "In the morning I do a quick wipe with toner on a cotton pad before the rest of my skincare.", "ja": "朝は拭き取り化粧水で軽く整えてからスキンケアを始める。", "es": "Por la mañana me paso el tónico con un algodón y luego sigo con la rutina.", "vi": "Buổi sáng mình lau nhẹ bằng toner rồi mới bắt đầu dưỡng da.", "de": "Morgens wische ich kurz mit Toner und Wattepad drüber, bevor der Rest der Pflege kommt."}, {"kor": "피부 예민할 땐 닦토는 쉬고 흡토만 해.", "eng": "When my skin is sensitive, I skip the wipe-off toner and only pat toner in.", "ja": "肌が敏感なときは拭き取りはお休みして、なじませるだけにしてる。", "es": "Cuando tengo la piel sensible, dejo el tónico con algodón y solo lo aplico a toquecitos.", "vi": "Khi da nhạy cảm thì mình tạm bỏ lau toner, chỉ vỗ cho thấm thôi.", "de": "Wenn meine Haut empfindlich ist, lasse ich das Abwischen weg und klopfe den Toner nur ein."}]}]'::jsonb, '''닦는 토너''의 앞 글자를 딴 줄임말로, 같은 토너라도 쓰는 방법을 구분하려고 뷰티 커뮤니티에서 쓰기 시작한 말이다. 두드려 흡수시키는 방법을 부르는 ''흡토''와 함께 쓰이며, 건강·뷰티 매체가 ''토너, 닦을까 바를까'' 같은 기사로 두 방법을 비교할 만큼 흔한 말이 됐다. 최초 사용처는 확인되지 않는다.', '{"de": "Kurzform aus den Anfangssilben von 닦는 토너; Beauty-Communitys begannen sie zu nutzen, um bei ein und demselben Toner die Anwendungsweise zu unterscheiden. Sie tritt zusammen mit 흡토 (einklopfen) auf und ist so geläufig, dass Gesundheits- und Beautymedien die beiden Methoden in Artikeln wie „Toner abwischen oder auftragen?“ vergleichen. Eine Erstverwendung ist nicht belegt.", "en": "Formed from the first syllables of 닦는 토너, it came into use in beauty communities to tell apart two ways of using the same toner. It goes together with 흡토, the pat-in method, and has become common enough that health and beauty media compare the two in articles like “Toner: wipe it or pat it?”. No first use is documented.", "es": "Formada con las primeras sílabas de 닦는 토너, empezó a usarse en comunidades de belleza para distinguir dos formas de usar el mismo tónico. Va junto a 흡토 (aplicarlo a toquecitos) y es tan común que medios de salud y belleza comparan ambos métodos en artículos como “Tónico: ¿pasarlo o aplicarlo?”. No consta su primer uso.", "ja": "「닦는 토너」の頭文字を取った略語で、同じ化粧水でも使い方を区別するために美容コミュニティで使われ始めた。たたき込む使い方を指す「흡토」とセットで使われ、健康・美容メディアが「化粧水、拭く?塗る?」といった記事で2つの方法を比べるほど一般的な言葉になった。初出は確認されていない。", "vi": "Ghép từ âm đầu của 닦는 토너, từ này được cộng đồng làm đẹp dùng để phân biệt hai cách dùng cùng một loại toner. Nó đi đôi với 흡토 (vỗ cho thấm) và phổ biến đến mức báo sức khỏe, làm đẹp so sánh hai cách qua các bài như “Toner: lau hay thoa?”. Không rõ lần dùng đầu tiên."}'::jsonb, '''닦토하다'', ''닦토용 토너''처럼 쓴다. 화장솜으로 문지르는 마찰이 있어 민감하거나 건조한 피부에는 흡토가 더 맞는다는 설명이 흔하다. ''닦토''와 ''닦는 토너'' 중 어느 쪽으로 검색해도 이 항목 하나로 나온다.', '{"de": "Man sagt 닦토하다 („mit Toner abwischen“) oder 닦토용 토너 („Toner zum Abwischen“). Weil das Reiben mit dem Wattepad Reibung erzeugt, heißt es oft, bei empfindlicher oder trockener Haut passe 흡토 besser. Ob man nach 닦토 oder 닦는 토너 sucht, man landet bei diesem einen Eintrag.", "en": "Used as 닦토하다 (to wipe with toner) or 닦토용 토너 (a wipe-off toner). Because rubbing with a cotton pad causes friction, you often hear that pat-in 흡토 suits sensitive or dry skin better. Searching 닦토 or 닦는 토너 brings up this single entry.", "es": "Se usa como 닦토하다 (pasar el tónico con algodón) o 닦토용 토너 (tónico para limpiar). Como frotar con el algodón genera fricción, es habitual oír que para piel sensible o seca va mejor 흡토. Busques 닦토 o 닦는 토너, aparece esta misma entrada.", "ja": "「닦토하다(拭き取りをする)」「닦토용 토너(拭き取り用化粧水)」のように使う。コットンでこする摩擦があるので、敏感肌や乾燥肌には흡토のほうが合うという説明をよく見かける。「닦토」「닦는 토너」のどちらで検索してもこの項目ひとつが出る。", "vi": "Dùng như 닦토하다 (lau bằng toner) hay 닦토용 토너 (toner để lau). Vì chà bông lên da gây ma sát nên người ta hay nói da nhạy cảm hoặc khô hợp với 흡토 hơn. Tìm 닦토 hay 닦는 토너 đều ra đúng mục này."}'::jsonb, array['흡토','수부지'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Wipe-off toner (on a cotton pad)"}, {"lang": "🇯🇵 JA", "text": "拭き取り化粧水"}, {"lang": "🇨🇳 ZH", "text": "擦拭型爽肤水"}, {"lang": "🇻🇳 VI", "text": "Toner lau (dùng bông)"}, {"lang": "🇪🇸 ES", "text": "Tónico con algodón"}, {"lang": "🇩🇪 DE", "text": "Toner zum Abwischen"}]'::jsonb, array['닦는 토너']),
('488', '흡토', 'Heup-to', 'beauty', null, '''흡수 토너'' — 손으로 두드려 흡수시키는 토너 사용법', '{"de": "Kurz für „Einzieh-Toner“ — Toner mit den Händen einklopfen", "en": "Short for “absorbing toner” — patting toner into the skin by hand", "es": "Abreviatura de “tónico de absorción”: aplicarlo a toquecitos con las manos", "ja": "「なじませる化粧水」の略 — 手でたたき込んで浸透させる使い方", "vi": "Viết tắt của “toner thấm” — vỗ toner bằng tay cho da hấp thụ"}'::jsonb, null, '[{"type": "명사", "definition": "''흡수(시키는) 토너''를 줄인 말. 토너를 손바닥에 덜어 얼굴에 가볍게 누르거나 두드려 피부에 흡수시키는 사용법, 또는 그렇게 쓰는 보습용 토너를 가리킨다. 화장솜으로 닦아 내는 ''닦토''와 구분하려고 생긴 말이라 거의 늘 짝으로 쓰인다.", "definition_i18n": {"de": "Kurzform von 흡수(시키는) 토너, „Toner zum Einziehenlassen“: die Methode, Toner in die Handfläche zu geben und sanft ins Gesicht zu drücken oder einzuklopfen, bis er einzieht — oder ein feuchtigkeitsspendender Toner, der so benutzt wird. Das Wort entstand zur Abgrenzung von 닦토, bei dem man mit dem Wattepad abwischt, und tritt daher fast immer als Paar auf.", "en": "A clipping of 흡수(시키는) 토너, “toner you let absorb”: the method of pouring toner into your palm and gently pressing or patting it into the face until it sinks in, or a hydrating toner meant to be used that way. The word arose to distinguish it from 닦토, where you wipe with a cotton pad, so the two almost always come as a pair.", "es": "Acortamiento de 흡수(시키는) 토너, “tónico que se deja absorber”: la forma de echar el tónico en la palma y presionarlo o darle toquecitos en la cara hasta que penetre, o un tónico hidratante pensado para usarse así. La palabra surgió para distinguirlo de 닦토, en el que se pasa con un algodón, así que casi siempre van en pareja.", "ja": "「흡수(시키는) 토너(なじませる化粧水)」の略。化粧水を手のひらに取り、顔に軽く押し当てたりたたき込んだりして肌に浸透させる使い方、またはそう使う保湿用化粧水を指す。コットンで拭き取る「닦토」と区別するために生まれた言葉なので、ほぼ必ずペアで使われる。", "vi": "Dạng rút gọn của 흡수(시키는) 토너, “toner để thấm”: cách đổ toner ra lòng bàn tay rồi ấn nhẹ hoặc vỗ lên mặt cho da hấp thụ, hoặc loại toner dưỡng ẩm dùng theo cách đó. Từ này ra đời để phân biệt với 닦토 — lau bằng bông — nên hai từ gần như luôn đi thành cặp."}, "examples": [{"kor": "건성이라 닦토 말고 흡토로 세 번 레이어링해.", "eng": "I have dry skin, so instead of wiping I pat toner in and layer it three times.", "ja": "乾燥肌だから拭き取りじゃなくて、なじませて3回重ねづけしてる。", "es": "Tengo la piel seca, así que en vez de pasarlo con algodón me lo aplico a toquecitos en tres capas.", "vi": "Da khô nên mình không lau mà vỗ toner cho thấm, lớp ba lần.", "de": "Ich habe trockene Haut, also wische ich nicht, sondern klopfe den Toner in drei Schichten ein."}, {"kor": "이 토너는 흡토용이라 화장솜 없이 손으로 발라.", "eng": "This toner is a pat-in type, so apply it by hand, no cotton pad.", "ja": "この化粧水はなじませるタイプだから、コットンなしで手でつけてね。", "es": "Este tónico es para aplicar a toquecitos, así que úsalo con las manos, sin algodón.", "vi": "Toner này là loại vỗ cho thấm, cứ thoa bằng tay, không cần bông.", "de": "Dieser Toner ist zum Einklopfen gedacht, also mit den Händen auftragen, ohne Wattepad."}]}]'::jsonb, '''흡수 토너''를 줄인 말로, 뷰티 커뮤니티에서 먼저 쓰이던 ''닦토''(닦는 토너)와 사용법을 구분하려고 나온 말이다. 두 방법을 비교하는 건강·뷰티 기사와 화장품 후기에서 짝으로 흔히 쓰이며, 토너를 여러 번 겹쳐 흡수시키는 루틴이 유행하면서 더 자주 쓰이게 됐다. 최초 사용처는 확인되지 않는다.', '{"de": "Kurzform von 흡수 토너; sie entstand in Beauty-Communitys, um die Anwendung vom dort bereits gebräuchlichen 닦토 (Abwisch-Toner) zu unterscheiden. In Gesundheits- und Beautyartikeln, die beide Methoden vergleichen, und in Produktbewertungen erscheint sie meist als Paar, und mit dem Trend, Toner in mehreren Schichten einziehen zu lassen, wurde sie noch häufiger. Eine Erstverwendung ist nicht belegt.", "en": "A clipping of 흡수 토너, it arose in beauty communities to distinguish the method from 닦토 (wipe-off toner), which was already in use there. The pair shows up together in health and beauty articles comparing the two methods and in product reviews, and it has become more frequent as routines of layering toner several times caught on. No first use is documented.", "es": "Acortamiento de 흡수 토너; surgió en comunidades de belleza para distinguir el método de 닦토 (tónico para limpiar), que ya se usaba allí. La pareja aparece junta en artículos de salud y belleza que comparan ambos métodos y en reseñas, y se volvió más frecuente con la moda de aplicar el tónico en varias capas. No consta su primer uso.", "ja": "「흡수 토너」の略で、美容コミュニティで先に使われていた「닦토(拭き取り化粧水)」と使い方を区別するために生まれた言葉。2つの方法を比べる健康・美容記事や化粧品レビューでペアでよく使われ、化粧水を何度も重ねてなじませるルーティンが流行したことでさらによく使われるようになった。初出は確認されていない。", "vi": "Dạng rút gọn của 흡수 토너, từ này xuất hiện trong cộng đồng làm đẹp để phân biệt với 닦토 (toner lau) vốn đã được dùng ở đó. Cặp từ thường đi cùng nhau trong các bài báo sức khỏe, làm đẹp so sánh hai cách và trong review mỹ phẩm, và càng được dùng nhiều khi trào lưu vỗ toner nhiều lớp lan rộng. Không rõ lần dùng đầu tiên."}'::jsonb, '''흡토하다'', ''흡토용 토너''처럼 쓰고, ''닦토 vs 흡토''처럼 두 말을 나란히 놓고 비교할 때 가장 많이 보인다. 마찰이 적어 건조하거나 민감한 피부에 권한다는 설명이 흔하다. ''흡토''와 ''흡수 토너'' 중 어느 쪽으로 검색해도 이 항목 하나로 나온다.', '{"de": "Man sagt 흡토하다 („Toner einklopfen“) oder 흡토용 토너 („Toner zum Einklopfen“); am häufigsten sieht man es im direkten Vergleich 닦토 vs 흡토. Da es kaum Reibung gibt, wird es oft für trockene oder empfindliche Haut empfohlen. Ob man nach 흡토 oder 흡수 토너 sucht, man landet bei diesem einen Eintrag.", "en": "Used as 흡토하다 (to pat toner in) or 흡토용 토너 (a pat-in toner), and seen most often in side-by-side comparisons like 닦토 vs 흡토. Because there is little friction, it is commonly recommended for dry or sensitive skin. Searching 흡토 or 흡수 토너 brings up this single entry.", "es": "Se usa como 흡토하다 (aplicar el tónico a toquecitos) o 흡토용 토너 (tónico para aplicar a toquecitos), y se ve sobre todo en comparaciones como 닦토 vs 흡토. Como apenas hay fricción, se suele recomendar para piel seca o sensible. Busques 흡토 o 흡수 토너, aparece esta misma entrada.", "ja": "「흡토하다(なじませる)」「흡토용 토너(なじませる用の化粧水)」のように使い、「닦토 vs 흡토」のように2つを並べて比べる場面で最もよく見かける。摩擦が少ないので乾燥肌や敏感肌に勧めるという説明が多い。「흡토」「흡수 토너」のどちらで検索してもこの項目ひとつが出る。", "vi": "Dùng như 흡토하다 (vỗ toner cho thấm) hay 흡토용 토너 (toner để vỗ), và hay gặp nhất khi đặt cạnh nhau so sánh kiểu 닦토 vs 흡토. Vì ít ma sát nên người ta thường khuyên dùng cho da khô hoặc nhạy cảm. Tìm 흡토 hay 흡수 토너 đều ra đúng mục này."}'::jsonb, array['닦토','수부지'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Pat-in toner (absorbed by hand)"}, {"lang": "🇯🇵 JA", "text": "なじませる化粧水(ハンドプレス)"}, {"lang": "🇨🇳 ZH", "text": "拍打吸收型爽肤水"}, {"lang": "🇻🇳 VI", "text": "Toner vỗ thấm"}, {"lang": "🇪🇸 ES", "text": "Tónico aplicado a toquecitos"}, {"lang": "🇩🇪 DE", "text": "Einklopf-Toner"}]'::jsonb, array['흡수 토너']);
